spec.expr:
sum(
  rate(
    kafka_server_brokertopicmetrics_count{
      job="kafka-brokers",
      name="MessagesInPerSec",
      topic="netflow"
    }[5m]
  )
)

100 *
(
  sum by (instance) (
    starrocks_be_disks_data_used_capacity{
      path="/mnt/disk1/starrocks_be"
    }
  )
  /
  sum by (instance) (
    starrocks_be_disks_total_capacity{
      path="/mnt/disk1/starrocks_be"
    }
  )
)

100 *
(
  sum by (instance) (
    hadoop_datanode_dfs_used{
      job="hdfs-datanodes",
      name="FSDatasetState"
    }
  )
  /
  sum by (instance) (
    hadoop_datanode_capacity{
      job="hdfs-datanodes",
      name="FSDatasetState"
    }
  )
)
